<?php
function doc_open($title,$p=null,$v=null){global $pdo;$f='Hospital';if(!empty(user()['facility'])){$q=$pdo->prepare('SELECT name FROM facilities WHERE id=?');$q->execute([user()['facility']]);$f=$q->fetchColumn()?:$f;}
 $o='<!doctype html><meta charset=utf-8><title>'.e($title).'</title><style>body{font:14px/1.5 system-ui,Arial,sans-serif;max-width:640px;margin:20px auto;padding:0 14px;color:#111}h2{margin:2px 0}.c{text-align:center;border-bottom:2px solid #000;padding-bottom:8px;margin-bottom:10px}table{width:100%;border-collapse:collapse;margin-bottom:10px}td,th{padding:4px 6px;border-bottom:1px dashed #999;text-align:left}.r{text-align:right}.sig{margin-top:34px;display:flex;justify-content:space-between;gap:20px}.sig span{border-top:1px solid #000;padding-top:3px;min-width:200px;text-align:center}.np{margin:16px 0}.box{border:2px solid #000;padding:8px;margin:10px 0}@media print{.np{display:none}}</style><div class=c><h2>'.e($f).'</h2><div>'.e($title).'</div></div>';
 if($p)$o.='<table><tr><td>Patient: <b>'.e($p['first_name'].' '.$p['last_name']).'</b><td>Patient no: <b>'.e($p['patient_no']).'</b><tr><td>ID: '.e($p['id_number']).'<td>Phone: '.e($p['phone']).'<tr><td>Gender / DOB: '.e($p['gender'].' '.$p['dob']).'<td>'.($v?'Visit #'.(int)$v['id'].' | ':'').e(date('d/m/Y H:i')).'</table>';
 return $o;}
function doc_close($back='queue.php'){return '<div class=sig><span>Served by: '.e(user()['name']).'</span><span>Patient / guardian</span></div><div class=np><button onclick=print()>Print</button> <a href="'.e($back).'">Back</a></div>';}
